'use client';

import { useEffect, useRef, useState, type ReactNode } from 'react';
import './flip-card.css';

export interface FlipCardProps {
  front: ReactNode;
  back: ReactNode;
  /** Labels for the flip buttons on each face. */
  showBackLabel?: string;
  showFrontLabel?: string;
  className?: string;
}

/**
 * Turns over to show a second face. Only the face you can see is
 * interactive (the other is inert), and focus follows to the new face's
 * button so keyboard users are never left on a hidden control.
 */
export function FlipCard({
  front,
  back,
  showBackLabel = 'Show details',
  showFrontLabel = 'Back',
  className = '',
}: FlipCardProps) {
  const [flipped, setFlipped] = useState(false);
  const frontFace = useRef<HTMLDivElement>(null);
  const backFace = useRef<HTMLDivElement>(null);
  const moved = useRef(false);

  useEffect(() => {
    frontFace.current?.toggleAttribute('inert', flipped);
    backFace.current?.toggleAttribute('inert', !flipped);
    if (moved.current)
      (flipped ? backFace : frontFace).current
        ?.querySelector<HTMLElement>('.mg-flip__button')
        ?.focus();
  }, [flipped]);

  const flip = () => {
    moved.current = true;
    setFlipped((value) => !value);
  };

  return (
    <div className={`mg-flip ${className}`} data-flipped={flipped}>
      <div className='mg-flip__inner'>
        <div ref={frontFace} className='mg-flip__face' aria-hidden={flipped}>
          <div className='mg-flip__content'>{front}</div>
          <button type='button' className='mg-flip__button' onClick={flip}>
            {showBackLabel}
          </button>
        </div>
        <div
          ref={backFace}
          className='mg-flip__face mg-flip__face--back'
          aria-hidden={!flipped}
        >
          <div className='mg-flip__content'>{back}</div>
          <button type='button' className='mg-flip__button' onClick={flip}>
            {showFrontLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

.mg-flip {
  perspective: 900px;
  color: var(--mg-text, #ffffff);
}

.mg-flip__inner {
  display: grid;
  transform-style: preserve-3d;
  transition: transform 600ms cubic-bezier(0.3, 0.9, 0.3, 1);
}

.mg-flip[data-flipped='true'] .mg-flip__inner {
  transform: rotateY(180deg);
}

.mg-flip__face {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 14px;
  grid-area: 1 / 1;
  min-height: 170px;
  padding: 20px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 16px;
  background: #121212;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}

.mg-flip__face--back {
  background: var(--mg-raised, #262626);
  color: #ffffff;
  transform: rotateY(180deg);
}

.mg-flip__button {
  align-self: flex-start;
  min-height: 44px;
  padding: 0 14px;
  border: 1px solid currentColor;
  border-radius: 8px;
  background: none;
  color: inherit;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.mg-flip__button:focus-visible {
  outline: 3px solid var(--mg-accent-text, #dce9f7);
  outline-offset: 2px;
}

/* Instant swap: no rotation, just show the right face. */
@media (prefers-reduced-motion: reduce) {
  .mg-flip__inner {
    transition: none;
    transform: none !important;
  }
  .mg-flip__face--back {
    transform: none;
  }
  .mg-flip[data-flipped='true'] .mg-flip__face:not(.mg-flip__face--back),
  .mg-flip[data-flipped='false'] .mg-flip__face--back {
    visibility: hidden;
  }
}
